/* NEXZO authoritative settings state v4: per-user, local-first, stale-cloud safe. */
(function(){
'use strict'; if(window.NEXZOSettings)return;
const DEFAULTS={mode:'dark',accent:'purple',font:'medium',density:'comfortable',motion:'smooth',sidebar:'expanded',defaultStudyTime:'1 Hour',weekStart:'Monday',language:'English',timeZone:'Asia/Kolkata',focusMode:false,autoSync:true,notifyTasks:true,notifyCommunity:true,notifyStreak:true,sound:true,emailDigest:'Off',profileVisibility:'Private',activityStatus:true,diagnostics:false,analytics:false,personalization:true,updatedAtMs:0};
const ACCENTS={purple:'#8b5cf6',blue:'#3b82f6',cyan:'#06b6d4',green:'#22c55e',pink:'#ec4899',silver:'#94a3b8'};
let current={...DEFAULTS}, currentUid='guest', cloudState='local', timer=0, initialized=false;
const parse=(v,f)=>{try{return JSON.parse(v)||f}catch{return f}};
const localKey=uid=>`nexzo:settings:v4:${uid||'guest'}`;
function authUser(){return window.NEXZOFirebaseUser||window.__NEXZO_AUTH_USER__||null}
function uid(){return authUser()?.uid||window.NEXZOSharedState?.currentUid?.()||'guest'}
function readFor(id=uid()){return {...DEFAULTS,...parse(localStorage.getItem(localKey(id)),{})}}
function saveLocal(value,id=currentUid){localStorage.setItem(localKey(id),JSON.stringify(value));localStorage.setItem('nexzo_settings',JSON.stringify(value));}
function resolvedTheme(mode){return mode==='system'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):mode}
function apply(value=current){const r=document.documentElement,b=document.body;if(!b)return;const accent=ACCENTS[value.accent]||value.accent||ACCENTS.purple,theme=resolvedTheme(value.mode),sidebar=['expanded','compact','icons'].includes(value.sidebar)?value.sidebar:'expanded';r.dataset.nexzoTheme=theme;r.dataset.nexzoAccent=value.accent||'purple';r.dataset.fontSize=value.font||'medium';r.dataset.density=value.density||'comfortable';r.dataset.sidebarMode=sidebar;r.style.colorScheme=theme;r.style.setProperty('--nx-user-accent',accent);r.style.setProperty('--nx-accent',accent);r.style.setProperty('--gold',accent);b.dataset.nexzoTheme=theme;b.dataset.density=value.density||'comfortable';b.dataset.sidebarMode=sidebar;b.dataset.nexzoMotion=value.motion||'smooth';b.dataset.fontSize=value.font||'medium';b.classList.toggle('nx-motion-off',value.motion==='off');b.classList.toggle('nx-motion-reduced',value.motion==='reduced');b.classList.toggle('nx-theme-light',theme==='light');b.classList.toggle('nx-focus-mode',value.focusMode===true);b.dataset.focusMode=value.focusMode===true?'on':'off';requestAnimationFrame(()=>window.dispatchEvent(new CustomEvent('nexzo:appearance-applied',{detail:{theme,accent,sidebar,font:value.font,density:value.density,motion:value.motion}})));}
function emit(source='local'){window.dispatchEvent(new CustomEvent('nexzo:settings-changed',{detail:{...current,source,cloudState}}));}
async function cloudContext(){const c=await window.NEXZOFirebase?.getContext?.({auth:true,firestore:true});if(!c?.auth?.currentUser)throw Object.assign(new Error('Not signed in'),{code:'auth/not-signed-in'});return c}
async function sync(){if(!current.autoSync||currentUid==='guest'){cloudState='local';return {status:cloudState}};clearTimeout(timer);try{const c=await cloudContext(),fs=c.firestoreTools,ref=fs.doc(c.db,'users',currentUid,'settings','main');await fs.setDoc(ref,{...current,uid:currentUid,updatedAtMs:current.updatedAtMs,updatedAt:fs.serverTimestamp()},{merge:true});cloudState='connected';localStorage.removeItem(`nexzo:settings:dirty:${currentUid}`);emit('cloud');return {status:cloudState}}catch(e){cloudState=e?.code==='permission-denied'?'permission-denied':navigator.onLine?'offline':'offline';localStorage.setItem(`nexzo:settings:dirty:${currentUid}`,'1');window.dispatchEvent(new CustomEvent('nexzo:cloud-status',{detail:{area:'settings',status:cloudState,message:e.message}}));return {status:cloudState,error:e}}}
function scheduleSync(){clearTimeout(timer);timer=setTimeout(sync,700)}
function set(patch,{syncCloud=true}={}){current={...current,...patch,updatedAtMs:Date.now()};saveLocal(current);apply(current);emit('local');if(syncCloud)scheduleSync();return {...current}}
async function hydrate(user){currentUid=user?.uid||uid();const local=readFor(currentUid);current=local;apply(current);emit('local');if(!user)return current;try{const c=await cloudContext(),fs=c.firestoreTools,snap=await fs.getDoc(fs.doc(c.db,'users',currentUid,'settings','main'));if(snap.exists()){const cloud=snap.data()||{},dirty=localStorage.getItem(`nexzo:settings:dirty:${currentUid}`)==='1';if(!dirty&&Number(cloud.updatedAtMs||0)>Number(local.updatedAtMs||0)){current={...DEFAULTS,...cloud};saveLocal(current);apply(current);emit('cloud-hydrate')}else if(Number(local.updatedAtMs||0)>Number(cloud.updatedAtMs||0))scheduleSync()}cloudState='connected'}catch(e){cloudState=e?.code==='permission-denied'?'permission-denied':'offline'}return current}
async function init(){if(initialized)return;initialized=true;currentUid=uid();current=readFor(currentUid);apply(current);if(matchMedia)matchMedia('(prefers-color-scheme: light)').addEventListener?.('change',()=>current.mode==='system'&&apply(current));try{const {auth,tools}=await window.NEXZOFirebase.getAuthContext();tools.onAuthStateChanged(auth,u=>{window.NEXZOFirebaseUser=u;hydrate(u)})}catch{hydrate(null)}window.addEventListener('online',()=>{if(localStorage.getItem(`nexzo:settings:dirty:${currentUid}`)==='1')sync()})}

function notify(title,body){if(Notification?.permission==='granted')new Notification(title,{body,icon:'favicon.png'});}
window.addEventListener('nexzo:community-reply',e=>{if(current.notifyCommunity)notify('NEXZO Community',e.detail?.message||'New community activity')});
window.addEventListener('nexzo:streak-at-risk',e=>{if(current.notifyStreak)notify('Study streak reminder',e.detail?.message||'Complete a study activity to protect your streak.')});
window.addEventListener('nexzo:task-reminder',e=>{if(current.notifyTasks)notify('Planner reminder',e.detail?.message||'A Planner task is due soon.')});
window.addEventListener('nexzo:rewards-updated',()=>{if(current.notifyTasks)notify('NEXZO reward','Your progress was updated.')});
window.NEXZOSettings=Object.freeze({defaults:DEFAULTS,accents:ACCENTS,get:()=>({...current}),set,apply,sync,hydrate,status:()=>cloudState,uid:()=>currentUid,init});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
